"""資源統計（ResourceList，工料總量）：查工料、展開每一筆用在詳細表哪些項目、拿展開核對資源統計的數量。

規則是從資料庫逆向來的（docs\\資料表與XML對照.md 2.3，ArchEx001、Class01、實案三案逐筆比過），
這裡改用電子標單的詳細表＋單價分析表照同一套展開。資料庫那一路（`db.budget.read_document`）先組出同樣的
`ETenderDocument`，資源統計的數量與複價也是用這支算的，所以兩支查詢工具只有這一份展開：

1. 起點是詳細表每一列有工項代碼（refItemCode）的葉項（analysis／general／variablePrice）。
   有單價分析就沿組成往下展：每一處用量 u＝上層用量 × 組成數量 ÷ 分析的 analysisOutputQuantity，
   組成本身是有子項的分析（巢狀）就再往下乘；analysisOutputQuantity 是 0 的分析不往下展。
   沒有單價分析、或分析沒有組成的工項，本身就是一筆資源：用量＝該列數量，複價＝該列複價。
2. 每一處的用量取 round(u, 4)、複價取 round(u × 組成單價, 4)，組成單價是單價分析那一列的 Price
   （資料庫的 budProjMrsB.cost；% 類是依比例算出的金額）。資源統計的數量＝各處用量加總。
3. 資源統計的複價看匯出當下有沒有重算：PCCES 4.3 重新總計後＝上一條的加總；沒重新總計就匯出的是
   usrAmt 快取（ArchEx001 示範檔是 2015 年的快取，81 筆只有 31 筆等於重算）。所以檔案有資源統計時
   數量、複價都照原值，只拿展開核對數量（`QuantityGap`）。
"""

from __future__ import annotations

from dataclasses import dataclass, field
from decimal import Decimal

from . import analysis as an
from .document import ETenderDocument, Item
from .edit import _index, _kind, _name
from .etender import LEAF_KINDS

# 資源統計 WorkItem 的 itemKind（對照文件 2.3）；詳細表的 costKind `#` 列在這裡是 formula
GENERAL = "general"
_ZERO = Decimal(0)


@dataclass(frozen=True)
class Use:
    """一筆工料用在詳細表的一處。`via` 是經過的單價分析（代碼, 名稱），由外往內；直接列在詳細表就是空的。"""

    path: str
    name: str
    via: tuple[tuple[str, str], ...]
    quantity: Decimal
    amount: Decimal


@dataclass
class Expansion:
    """展開結果：每個工料代碼的各處用途（照詳細表先序），與推算時要用的名稱、單位、種類、單價。"""

    uses: dict[str, list[Use]] = field(default_factory=dict)
    meta: dict[str, tuple[str, str, str, Decimal | None]] = field(default_factory=dict)
    # 標成有單價分析、單價分析表卻找不到的詳細表列（項次＋名稱）：沒有展開，數量會少
    skipped: list[str] = field(default_factory=list)
    _at: dict[tuple, int] = field(default_factory=dict, repr=False)

    def quantity(self, code: str) -> Decimal:
        return sum((u.quantity for u in self.uses.get(code, [])), _ZERO)

    def amount(self, code: str) -> Decimal:
        return sum((u.amount for u in self.uses.get(code, [])), _ZERO)

    def _add(self, code: str, row: int, use: Use, meta: tuple[str, str, str, Decimal | None]) -> None:
        # 同一列詳細表經同一串分析碰到同一個工料兩次以上（分析裡同代碼兩列，Class01 壹.二.d）併成一處：
        # 各次先各自進位再加，總數不變；列兩行一模一樣的「那一處」反而看不懂
        lst = self.uses.setdefault(code, [])
        key = (code, row, use.via)
        if key in self._at:
            i = self._at[key]
            old = lst[i]
            lst[i] = Use(old.path, old.name, old.via, old.quantity + use.quantity, old.amount + use.amount)
        else:
            self._at[key] = len(lst)
            lst.append(use)
        self.meta.setdefault(code, meta)


def _unit(it: Item) -> str:
    return (it.value("Unit", "zh-TW") or "").strip()


def _aoq(w: Item) -> Decimal:
    s = w.attrs.get("analysisOutputQuantity", "1").strip() or "1"
    return Decimal(s)


def expand(doc: ETenderDocument) -> Expansion:
    """照模組說明第 1、2 條展開整份預算書。"""
    idx = _index(doc)
    cbl: dict[str, Item] = {}
    for w in (doc.cost_breakdown_list.items if doc.cost_breakdown_list is not None else []):
        cbl.setdefault(an.code(w), w)  # 同一分析被兩列用到時有兩份，內容相同（analysis.same_analysis），取第一份
    exp = Expansion()

    def walk(w: Item, qty: Decimal, via: tuple, row: int, path: str, name: str) -> None:
        aoq = _aoq(w)
        if aoq == 0:
            return
        via = via + ((an.code(w), an.name(w)),)
        for c in w.children:
            u = qty * (c.decimal("Quantity") or _ZERO) / aoq
            if c.children:
                walk(c, u, via, row, path, name)
                continue
            price = c.decimal("Price")
            exp._add(an.code(c), row, Use(path, name, via, an.rnd(u, 4), an.rnd(u * (price or _ZERO), 4)),
                     (an.name(c), _unit(c), an.kind(c), price))

    for row, (_, it) in enumerate(doc.detail_list.iter_items()):
        if it.children or _kind(it) not in LEAF_KINDS:
            continue
        code = it.attrs.get("refItemCode", "").strip()
        if not code:
            continue
        path, name, qty = idx.path(it), _name(it), it.decimal("Quantity") or _ZERO
        if _kind(it) == an.ANALYSIS_KIND or code in cbl:
            w = cbl.get(code)
            if w is None:
                exp.skipped.append(f"{path} {name}")
                continue
            if w.children:
                walk(w, qty, (), row, path, name)
                continue
        exp._add(code, row, Use(path, name, (), qty, it.decimal("Amount") or _ZERO),
                 (name, _unit(it), _kind(it), it.decimal("Price")))
    return exp


@dataclass
class Resource:
    """資源統計的一筆工料。quantity／price／amount 是資源統計原值；沒有資源統計時是展開推算的。"""

    code: str
    name: str
    unit: str
    kind: str
    quantity: Decimal | None
    price: Decimal | None
    amount: Decimal | None
    uses: list[Use]

    @property
    def expanded_quantity(self) -> Decimal:
        return sum((u.quantity for u in self.uses), _ZERO)


@dataclass(frozen=True)
class QuantityGap:
    """資源統計的數量跟展開加總對不上；listed 是 None＝展開有、資源統計沒有這筆。"""

    code: str
    name: str
    listed: Decimal | None
    expanded: Decimal


def resource_list(doc: ETenderDocument, exp: Expansion | None = None) -> tuple[list[Resource], bool]:
    """（資源統計的每一筆工料, 是不是推算的）。有 ResourceList 照它的順序與原值；沒有就用展開推算、依工料代碼排。"""
    exp = exp or expand(doc)
    if doc.resource_list is not None:
        out = []
        for w in doc.resource_list.items:
            if w.tag != "WorkItem":
                continue
            c = an.code(w)
            out.append(Resource(c, an.name(w), _unit(w), an.kind(w), w.decimal("Quantity"), w.decimal("Price"),
                                w.decimal("Amount"), exp.uses.get(c, [])))
        return out, False
    out = []
    for c in sorted(exp.uses):
        name, unit, kind, price = exp.meta[c]
        # 只有一般工料的單價全案共用；變動單價、% 類各分析不同，資源統計本來就不列單價
        out.append(Resource(c, name, unit, kind, exp.quantity(c), price if kind == GENERAL else None,
                            exp.amount(c), exp.uses[c]))
    return out, True


def quantity_gaps(resources: list[Resource], exp: Expansion) -> list[QuantityGap]:
    """資源統計的數量≠展開加總的工料，加上展開有、資源統計沒列的（照工料代碼排在後面）。"""
    gaps = [QuantityGap(r.code, r.name, r.quantity, exp.quantity(r.code))
            for r in resources if (r.quantity or _ZERO) != exp.quantity(r.code)]
    listed = {r.code for r in resources}
    gaps += [QuantityGap(c, exp.meta[c][0], None, exp.quantity(c)) for c in sorted(set(exp.uses) - listed)]
    return gaps


@dataclass
class ResourceReport:
    hits: list[Resource]  # 依工料代碼排
    estimated: bool  # 檔案沒有資源統計，數量複價是展開推算的
    gaps: list[QuantityGap]  # 全案；推算時是空的
    skipped: list[str]
    n_resources: int


def find_resources(doc: ETenderDocument, keyword: str | None = None, item_code: str | None = None) -> ResourceReport:
    """依名稱關鍵字（不分大小寫、子字串）或工料代碼前綴找資源統計的工料；兩個都給時要同時符合。

    結果依工料代碼排：資源統計原本的順序是匯出那台工料庫的 pubCode（對照文件 2.3），換一台匯出就不同，
    依代碼排兩條路（XML、資料庫）的輸出才一樣，同類工料也排在一起。
    """
    kw = keyword.strip().lower() if keyword and keyword.strip() else None
    prefix = item_code.strip() if item_code and item_code.strip() else None
    if kw is None and prefix is None:
        raise ValueError("keyword 與 item_code 至少要給一個")
    exp = expand(doc)
    res, estimated = resource_list(doc, exp)
    hits = [r for r in res
            if (kw is None or kw in r.name.lower()) and (prefix is None or r.code.startswith(prefix))]
    hits.sort(key=lambda r: r.code)
    return ResourceReport(hits, estimated, [] if estimated else quantity_gaps(res, exp), exp.skipped, len(res))
